using System;
using System.Reflection;
using UnityEngine;
public static class ProbeLoading
{
    public static void Run()
    {
        Type t = Type.GetType("UI.Common.UILoadingPanel, Assembly-CSharp");
        Debug.Log("[Probe] UILoadingPanel type = " + (t == null ? "NULL" : t.FullName));
        Type u = Type.GetType("QTower.Common.Defines.UIDefines, Assembly-CSharp");
        Debug.Log("[Probe] UIDefines type = " + (u == null ? "NULL" : u.FullName));
        if (u != null)
        {
            foreach (FieldInfo f in u.GetFields(BindingFlags.Public | BindingFlags.Static))
                Debug.Log("[Probe] UIDefines." + f.Name + " = " + f.GetValue(null));
        }
        Type gc = Type.GetType("GameController, Assembly-CSharp");
        Debug.Log("[Probe] GameController = " + (gc == null ? "NULL" : gc.FullName));
        if (gc != null)
        {
            MethodInfo[] ms = gc.GetMethods(BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Public);
            foreach (MethodInfo m in ms)
                if (m.Name.Contains("Loading") || m.Name.Contains("switchTo"))
                    Debug.Log("[Probe] method " + m.Name);
        }
    }
}
